"""Single-reader judgments from full saved criteria; no algorithmic eligibility labeling."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
J=[]
def add(n,d,label,cohort,quote,rationale,biomarker='None specified for diagnosis compatibility.',uncertainty='Cohort/site availability not established by overall recruitment status.',constraints='See complete inclusion/exclusion text; no individual eligibility adjudication.',exclusion_mode=None,extra_evidence=None):
    J.append(dict(nct_id=n,diagnosis=d,label=label,cohort=cohort,decisive_excerpt=quote,rationale=rationale,extra_biomarker_requirement=biomarker,protocol_uncertainty=uncertainty,exclusions_and_other_constraints=constraints,exclusion_mode=exclusion_mode,extra_evidence=extra_evidence or []))

